CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role text NOT NULL CHECK(role='admin'), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') $$;
REVOKE ALL ON FUNCTION public.is_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_admin() TO anon,authenticated;
CREATE TABLE public.properties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, slug text UNIQUE NOT NULL, description text NOT NULL DEFAULT '', price bigint NOT NULL DEFAULT 0 CHECK(price>=0), transaction_type text NOT NULL DEFAULT 'Acheter' CHECK(transaction_type IN ('Acheter','Louer')), property_type text NOT NULL DEFAULT 'Villa', location text NOT NULL DEFAULT 'Dakar', bedrooms integer NOT NULL DEFAULT 0 CHECK(bedrooms>=0), bathrooms integer NOT NULL DEFAULT 0 CHECK(bathrooms>=0), surface integer NOT NULL DEFAULT 0 CHECK(surface>=0), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','sold','rented')), featured boolean NOT NULL DEFAULT false, amenities text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.properties TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.properties TO authenticated; GRANT ALL ON public.properties TO service_role;
ALTER TABLE public.properties ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_properties ON public.properties FOR SELECT TO anon,authenticated USING(status='published');
CREATE POLICY admin_properties ON public.properties FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE TABLE public.property_images(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES public.properties(id) ON DELETE CASCADE, image_url text NOT NULL, display_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.property_images TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.property_images TO authenticated; GRANT ALL ON public.property_images TO service_role;
ALTER TABLE public.property_images ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_images ON public.property_images FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.properties p WHERE p.id=property_id AND p.status='published'));
CREATE POLICY admin_images ON public.property_images FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE INDEX property_images_property_idx ON public.property_images(property_id);
CREATE TABLE public.contact_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid REFERENCES public.properties(id) ON DELETE SET NULL, full_name text NOT NULL CHECK(length(full_name) BETWEEN 2 AND 150), phone text NOT NULL CHECK(length(phone) BETWEEN 6 AND 30), email text NOT NULL CHECK(length(email)<=254), subject text NOT NULL DEFAULT '', message text NOT NULL CHECK(length(message) BETWEEN 10 AND 5000), created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.contact_requests TO anon; GRANT SELECT,INSERT,DELETE ON public.contact_requests TO authenticated; GRANT ALL ON public.contact_requests TO service_role;
ALTER TABLE public.contact_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY send_request ON public.contact_requests FOR INSERT TO anon,authenticated WITH CHECK(true);
CREATE POLICY admin_requests ON public.contact_requests FOR SELECT TO authenticated USING(public.is_admin());
CREATE POLICY admin_delete_requests ON public.contact_requests FOR DELETE TO authenticated USING(public.is_admin());
CREATE INDEX contact_requests_property_idx ON public.contact_requests(property_id);